(6047745, 889827, 24951, '<td valign="top">Great detail and texture</td>', 'Great detail and texture', '2010-06-09 02:51:12.000000', NULL, 1),
(6047762, 889691, 15511, '<td valign="top">Beautiful image. The color is imperfect - highlights need more red and overall too much blue. Regardless, what a moment.</td>', 'Beautiful image. The color is imperfect - highlights need more red and overall too much blue. Regardless, what a moment.', '2010-06-09 03:07:57.000000', NULL, 1),
