(6047848, 888078, 110221, '<td valign="top">Effective choice of both aperture and shutterspeed.</td>', 'Effective choice of both aperture and shutterspeed.', '2010-06-09 05:39:55.000000', NULL, 1),
(6047850, 889608, 110221, '<td valign="top">Effective lateral thinking insofar as making a lovely photo eligible for the challenge by virtue of the title choice. Love the pensive expression, would like to see how it would look with a slight increase in saturation.</td>', 'Effective lateral thinking insofar as making a lovely photo eligible for the challenge by virtue of the title choice. Love the pensive expression, would like to see how it would look with a slight increase in saturation.', '2010-06-09 05:42:17.000000', NULL, 1),
(6047855, 888815, 105130, '<td valign="top">I recognise that a lot of thought and effort went into this shot, but I think you will drop some points due to the ''muddy'' processing technique. It''s a shame as what you''ve done here is very creative.</td>', 'I recognise that a lot of thought and effort went into this shot, but I think you will drop some points due to the ''muddy'' processing technique. It''s a shame as what you''ve done here is very creative.', '2010-06-09 06:01:58.000000', NULL, 1),
(6047862, 889523, 105130, '<td valign="top">You know, I always tell myself that I''m bored of drop shots, and then something like this comes around and still manages to take my breath away. Congratulations.</td>', 'You know, I always tell myself that I''m bored of drop shots, and then something like this comes around and still manages to take my breath away. Congratulations.', '2010-06-09 06:10:13.000000', NULL, 1),
(6047864, 889691, 105130, '<td valign="top">Pin sharp and a wonderful moment, well done. This should make it into the top three fairly easily.</td>', 'Pin sharp and a wonderful moment, well done. This should make it into the top three fairly easily.', '2010-06-09 06:15:50.000000', NULL, 1),
