(6051507, 889463, 41976, '<td valign="top">I really don''t think this meets the sprite of the challenge.</td>', 'I really don''t think this meets the sprite of the challenge.', '2010-06-11 13:47:59.000000', NULL, 1),
(6051513, 889608, 41976, '<td valign="top">I really don''t think this reflects the sprite of the challenge, everyone has two eyes.  As a portrait, try getting about 10 or 12 feet from the subject and go with a f/8 (or so) setting.  That would get most of the facial features in focus.  Very important; focus on the eyes.  That will make or break your portrait.  Also use unsharp mask to sharpen the result.</td>', 'I really don''t think this reflects the sprite of the challenge, everyone has two eyes.  As a portrait, try getting about 10 or 12 feet from the subject and go with a f/8 (or so) setting.  That would get most of the facial features in focus.  Very important; focus on the eyes.  That will make or break your portrait.  Also use unsharp mask to sharpen the result.', '2010-06-11 13:54:44.000000', NULL, 1),
(6051516, 888043, 41976, '<td valign="top">I''m not sure how this met the challenge... there''s four of them.</td>', 'I''m not sure how this met the challenge... there''s four of them.', '2010-06-11 13:55:29.000000', NULL, 1),
