(6063223, 889523, 39057, '<td valign="top">Hello again. How did you get the golden color? Also...did you use a mirror or glass for the surface?<br/> <br/>Thanks</td>', 'Hello again. How did you get the golden color? Also...did you use a mirror or glass for the surface? Thanks', '2010-06-20 13:30:50.000000', NULL, 0),
(6063245, 889523, 59267, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by kenskid:</b></div><hr/><i> Hello again. How did you get the golden color? Also...did you use a mirror or glass for the surface?<br/> <br/>Thanks </i></td></tr></table> <br/>A gel or filter for flash unit. A glass for surface.</td>', 'Originally posted by kenskid: Hello again. How did you get the golden color? Also...did you use a mirror or glass for the surface? Thanks  A gel or filter for flash unit. A glass for surface.', '2010-06-20 14:27:59.000000', NULL, 0),
